/* Read-only author textbook. Separate from rolecraft-v1 and the controlled e03 generation input. */
const textbookChapterIds=Object.freeze(['f01','f02','c01','c02','c03','e01','e02','e03','e04','e05','p01','p02']);
const textbookSectionIds=Object.freeze(['scope','outcomes','concepts','case','example','practice','validation','sources','reflection']);
const textbookReader={mode:'chapter',chapter:'c01',source:'current'};
const textbookEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const textbookText=value=>typeof value==='string'?value:JSON.stringify(value??'',null,2);
const textbookList=value=>Array.isArray(value)?value:[];
const textbookStatusLabels={reviewed_with_limitations:'AI文稿审校完成（有范围限制）',draft:'AI作者草稿',needs_revision:'需返修',not_reviewed:'未独立审校',not_done:'未完成',not_run:'未运行',not_verified:'未验证',source_checked:'来源已检查（非运行或学习效果证明）',original_design:'原创教学设计',pseudocode:'伪代码',unexecuted_code:'未执行代码',paper_exercise:'纸面推演',agent_authored_draft:'作者代理编写草稿',scaffold:'脚手架练习',independent:'独立实现练习',transfer:'未知场景迁移练习'};
const textbookStatus=value=>textbookStatusLabels[value]||textbookText(value||'未提供');
function textbookSetLocation(loc){textbookReader.source=loc.source==='original'||loc.source==='v05'?'v05':'current';if(loc.target==='sample'){textbookReader.mode='sample';return;}if(loc.target&&loc.target!=='agent'&&!textbookChapterIds.includes(loc.target)){textbookReader.mode='sample';return;}textbookReader.mode=loc.chapter==='all'?'all':'chapter';textbookReader.chapter=loc.target==='agent'||!loc.target?(loc.chapter||'c01'):loc.target;}
function textbookPackage(source='current'){const book=source==='v05'?(typeof textbookV05Data==='undefined'?null:textbookV05Data):(typeof textbookData==='undefined'?null:textbookData);if(!book)return {book:null,problem:source==='v05'?'v0.5原稿资源尚未加载。':'本轮c01示范正文尚未加载。v0.5原稿可明确对照，不能作为本轮新稿。'};if(!['1.0','1.1'].includes(book.schemaVersion)||typeof book.version!=='string'||!book.version||!Array.isArray(book.chapters)||book.chapters.length!==12)return {book:null,problem:'教材包版本或十二章结构不完整，暂不显示为完整新教材。'};const ids=book.chapters.map(c=>c?.id);if(new Set(ids).size!==12||!textbookChapterIds.every(id=>ids.includes(id))||book.chapters.some(c=>c.moduleId!==c.id||typeof c.title!=='string'||!Array.isArray(c.sections)||c.sections.length!==9||!textbookSectionIds.every((id,i)=>c.sections[i]?.id===id&&typeof c.sections[i]?.bodyMarkdown==='string'&&c.sections[i].bodyMarkdown.trim())))return {book:null,problem:'教材章标识或九节正文资源不完整。未回退或继承旧版通过结论。'};if(source!=='v05'&&(!textbookIsPilot(book)||!textbookPilotComplete(book.chapters.find(c=>c.id==='c01'))))return {book:null,problem:'本轮c01示范的小课正文尚不完整。可以查看原v0.5稿，但不视为新示范。'};return {book,problem:''};}
function textbookMetaFor(book){return book?.version==='textbook-draft-0.5'?(typeof textbookV05PackageMeta==='undefined'?null:textbookV05PackageMeta):(typeof textbookPackageMeta==='undefined'?null:textbookPackageMeta);}
// Only escaped text gains a small set of local formatting tags; Markdown links/HTML/images never execute.
function textbookInline(text){return textbookEscape(text).replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');}
function textbookMarkdown(text,headingOffset=2){const lines=String(text??'').replace(/\r\n?/g,'\n').split('\n'),out=[];let paragraph=[],list=[],listType='',code=null,language='';const flushParagraph=()=>{if(paragraph.length){out.push('<p>'+paragraph.map(textbookInline).join('<br>')+'</p>');paragraph=[];}};const flushList=()=>{if(list.length){out.push('<'+listType+'>'+list.map(x=>'<li>'+textbookInline(x)+'</li>').join('')+'</'+listType+'>');list=[];listType='';}};const flush=()=>{flushParagraph();flushList();};const cells=line=>line.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(x=>x.trim());for(let i=0;i<lines.length;i++){const line=lines[i];if(code!==null){if(/^\s*```\s*$/.test(line)){out.push('<pre><code>'+textbookEscape(code.join('\n'))+'</code></pre>');code=null;}else code.push(line);continue;}const fence=line.match(/^\s*```([^`]*)$/);if(fence){flush();language=fence[1].trim();code=[];if(language)out.push(['text','plaintext','diagram'].includes(language)?'<p class="note">文字示意图</p>':'<p class="note">代码格式：'+textbookEscape(language)+' · 网页不执行代码</p>');continue;}if(!line.trim()){flush();continue;}const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){flush();const level=Math.min(6,heading[1].length+headingOffset);out.push('<h'+level+'>'+textbookInline(heading[2])+'</h'+level+'>');continue;}if(line.includes('|')&&i+1<lines.length&&/^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(lines[i+1])){flush();const head=cells(line),rows=[];i+=2;while(i<lines.length&&lines[i].trim()&&lines[i].includes('|')){rows.push(cells(lines[i]));i++;}i--;out.push('<div class="textbook-table"><table><thead><tr>'+head.map(c=>'<th scope="col">'+textbookInline(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+head.map((_,j)=>'<td>'+textbookInline(row[j]||'')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');continue;}const item=line.match(/^\s*(?:([-*])\s+|\d+[.)]\s+)(.+)$/);if(item){flushParagraph();const type=item[1]?'ul':'ol';if(listType&&listType!==type)flushList();listType=type;list.push(item[2]);continue;}flushList();if(/^>\s?/.test(line)){flushParagraph();out.push('<blockquote>'+textbookInline(line.replace(/^>\s?/,''))+'</blockquote>');continue;}paragraph.push(line);}flush();if(code!==null)out.push('<pre><code>'+textbookEscape(code.join('\n'))+'</code></pre>');return '<div class="textbook-markdown">'+out.join('')+'</div>';}
function textbookValues(value){if(Array.isArray(value))return '<ul>'+value.map(v=>'<li>'+textbookEscape(textbookText(v))+'</li>').join('')+'</ul>';return typeof value==='object'&&value!==null?'<pre class="textbook-metadata">'+textbookEscape(textbookText(value))+'</pre>':'<p>'+textbookEscape(textbookText(value||'未提供'))+'</p>';}
function textbookAllowedSource(url){try{const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password&&(!u.port||u.port==='443')&&['www.anthropic.com','genai.owasp.org','cheatsheetseries.owasp.org','developers.openai.com','platform.openai.com','docs.langchain.com','docs.python.org','www.microsoft.com','rfc-editor.org','www.rfc-editor.org','git-scm.com','developer.mozilla.org','opentelemetry.io'].includes(u.hostname)?u.href:null;}catch{return null;}}
function textbookSourceHTML(source){const url=textbookAllowedSource(source.url);return '<article class="textbook-source"><h4>'+ (url?'<a href="'+textbookEscape(url)+'" target="_blank" rel="noopener noreferrer">'+textbookEscape(source.title||source.id)+'</a>':textbookEscape(source.title||source.id))+'</h4><p>'+textbookEscape(source.id)+' · '+textbookEscape(source.organization||source.type||'内部参考')+'</p><p>版本：'+textbookEscape(source.version||'未知')+' · 访问：'+textbookEscape(source.accessedAt||'未知')+'</p><h5>具体位置</h5>'+textbookValues(source.locator||source.locators||source.sections||'未提供')+'<h5>支持范围</h5>'+textbookValues(source.supports||source.supportScope||'未提供')+'<p>来源访问状态：'+textbookEscape(textbookStatus(source.verification||'未提供'))+'</p><h5>限制</h5>'+textbookValues(source.limits||'来源链接不证明本章运行或学习效果')+'</article>';}
function textbookContentReview(book){const report=book?.version==='textbook-draft-0.5'?(typeof textbookV05ContentReviewData==='undefined'?null:textbookV05ContentReviewData):(typeof textbookContentReviewData==='undefined'?null:textbookContentReviewData),meta=textbookMetaFor(book);return report&&meta&&typeof meta.sourceSha256==='string'&&/^[a-f0-9]{64}$/.test(meta.sourceSha256)&&(report.textbookVersion||report.version)===book.version&&report.inputSha256===meta.sourceSha256?report:null;}
function textbookAuditMatches(report){const {book}=textbookPackage(),meta=typeof textbookPackageMeta==='undefined'?null:textbookPackageMeta;return Boolean(book&&meta&&typeof meta.sourceSha256==='string'&&/^[a-f0-9]{64}$/.test(meta.sourceSha256)&&report?.textbookVersion===book.version&&report?.textbookInputSha256===meta.sourceSha256);}
function textbookReviewHTML(book,chapterId=''){if(textbookIsPilot(book)&&chapterId&&chapterId!=='c01')return '<p>本章沿用 v0.5 原稿；本轮 v0.6 独立审校只针对 c01 示范，不对本章重新授审核。原版报告可在 v0.5 全书中查阅。</p>';const r=textbookContentReview(book);let html='<p>'+(textbookIsPilot(book)?'本轮仅 c01 示范的独立 AI 内容审校：':'v0.5 原稿的独立 AI 内容审校：')+(r?textbookEscape(textbookStatus(r.overall||r.status||r.conclusion||'已交独立报告，详见范围')):'未匹配当前稿（缺报告或版本/源包哈希不匹配）')+'。人类行业专家审核：未完成；真实学员学习效果：未验证。</p>';if(r){html+='<details class="textbook-review"><summary>当版独立审校范围与问题记录</summary><p>绑定教材：'+textbookEscape(book.version)+' · 作者源包 SHA256（打包记录）：'+textbookEscape(r.inputSha256)+'</p><p>审校者：'+textbookEscape(textbookText(r.reviewer||r.reviewerRole||'独立内容审校员（AI）'))+'</p><h4>实际范围</h4>'+textbookValues(r.scope||r.reviewScope||r.assessmentScope||r.coverage||'见独立报告');const chapters=textbookList(r.chapterResults||r.chapters||r.chapterReviews);const selected=chapterId?chapters.filter(c=>(c.moduleId||c.chapterId||c.id)===chapterId):chapters;if(selected.length)html+='<h4>逐章记录</h4>'+textbookValues(selected);const issues=textbookList(r.defects||r.issues||r.findings);const selectedIssues=chapterId?issues.filter(v=>v.chapterId===chapterId||v.moduleId===chapterId||textbookList(v.moduleIds||v.chapterIds).includes(chapterId)||!v.chapterId&&!v.moduleId&&!Array.isArray(v.moduleIds)&&!Array.isArray(v.chapterIds)):issues;if(selectedIssues.length)html+='<h4>问题与返修复核</h4>'+textbookValues(selectedIssues);html+='<h4>限制</h4>'+textbookValues(r.remainingGaps||r.limits||r.limitations||'AI审校不替代案例执行、人类专业审核或真实学习效果')+'</details>';}return html;}
function textbookKnowledgeHTML(point){return '<article class="textbook-knowledge"><h4>'+textbookEscape(point.id)+' · '+textbookEscape(point.title)+'</h4>'+textbookMarkdown(point.explanation||'')+'<p class="note">目标：'+textbookEscape(textbookList(point.objectiveIds).join('、'))+' · 对应练习：'+textbookEscape(textbookList(point.exerciseIds).join('、'))+'</p><h5>情景题 '+textbookEscape(point.questionId||'')+'</h5>'+textbookMarkdown(textbookText(point.question||point.directQuestion||point.primaryQuestion||''))+'<details><summary>参考结论、条件推理和误区</summary>'+textbookMarkdown(textbookText(point.answer||''))+textbookMarkdown(textbookText(point.analysis||''))+'</details><h5>新条件迁移</h5>'+textbookMarkdown(textbookText(point.transfer||point.transferQuestion||''))+'<p class="note">依据：'+textbookEscape(textbookList(point.sourceIds).join('、')||'原创教学设计')+' · '+textbookEscape(point.supportScope||'适用范围见正文')+'</p></article>';}
function textbookExerciseHTML(exercise){return '<article class="textbook-exercise"><h4>'+textbookEscape(exercise.id)+' · '+textbookEscape(exercise.title||textbookStatus(exercise.level))+'</h4><p class="state-label">'+textbookEscape(textbookStatus(exercise.level))+' · 执行状态：'+textbookEscape(textbookStatus(exercise.executionStatus||'not_run'))+'</p><h5>任务</h5>'+textbookMarkdown(exercise.task||'')+'<h5>输入</h5>'+textbookValues(exercise.input)+'<h5>提交物</h5>'+textbookValues(exercise.deliverables)+'<details><summary>参考解法与反馈（先独立尝试）</summary>'+textbookMarkdown(textbookText(exercise.referenceSolution||''))+textbookMarkdown(textbookText(exercise.feedback||''))+'<h5>新条件迁移</h5>'+textbookMarkdown(textbookText(exercise.transferPrompt||''))+'<h5>正常、边界、失败预期</h5><dl><dt>正常</dt><dd>'+textbookEscape(textbookText(exercise.normal||''))+'</dd><dt>边界</dt><dd>'+textbookEscape(textbookText(exercise.boundary||''))+'</dd><dt>失败</dt><dd>'+textbookEscape(textbookText(exercise.failure||''))+'</dd></dl></details><p class="note">知识点：'+textbookEscape(textbookList(exercise.knowledgePointIds).join('、'))+'。公开参考解法不构成独立保留题；网页不会自动判作品通过。</p></article>';}
function textbookChapterHTML(book,chapter){if(textbookIsPilot(book)&&chapter.id==='c01')return textbookPilotChapterHTML(book,chapter);return textbookStructuredChapterHTML(book,chapter);}
function textbookStructuredChapterHTML(book,chapter){const sources=textbookList(book.sources).filter(s=>textbookList(chapter.sourceIds).includes(s.id));return '<article class="card lesson textbook-chapter" id="textbook-chapter-'+textbookEscape(chapter.id)+'"><span class="eyebrow">'+textbookEscape(chapter.id)+' · '+textbookEscape(chapter.version||book.version)+' · AI 作者草稿</span><h2 id="textbook-title-'+textbookEscape(chapter.id)+'">'+textbookEscape(chapter.title)+'</h2><div class="callout"><strong>学习目标</strong>'+textbookValues(chapter.objectives)+'<strong>先修模块</strong>'+textbookValues(chapter.prerequisites)+'<p>先修需要作品证据；可以预览，阅读不自动授予通过。</p></div>'+textbookReviewHTML(book,chapter.id)+'<div class="textbook-sections-nav" aria-label="本章九节">'+chapter.sections.map((s,i)=>'<a href="#textbook-'+textbookEscape(chapter.id)+'-'+textbookEscape(s.id)+'" data-textbook-anchor="textbook-'+textbookEscape(chapter.id)+'-'+textbookEscape(s.id)+'">'+(i+1)+'. '+textbookEscape(s.title)+'</a>').join('')+'</div>'+chapter.sections.map((s,i)=>'<section class="textbook-section" id="textbook-'+textbookEscape(chapter.id)+'-'+textbookEscape(s.id)+'"><h3>'+String(i+1).padStart(2,'0')+' · '+textbookEscape(s.title)+'</h3>'+textbookMarkdown(s.bodyMarkdown)+'<p class="note">本节资料：'+textbookEscape(textbookList(s.sourceIds).join('、')||'原创教学设计/支持范围见来源节')+'</p></section>').join('')+'<details><summary>逐知识点讲解、情景题与迁移</summary>'+textbookList(chapter.knowledgePoints).map(textbookKnowledgeHTML).join('')+'</details><details><summary>分层任务、参考解法与反馈</summary>'+textbookList(chapter.exercises).map(textbookExerciseHTML).join('')+'</details><details><summary>案例执行与验证记录</summary>'+textbookList(chapter.examples).map(e=>'<article class="textbook-example"><h4>'+textbookEscape(e.title||e.id)+'</h4><p>'+textbookEscape(textbookStatus(e.kind))+' · '+textbookEscape(textbookStatus(e.executionStatus||'not_run'))+'</p><h5>环境</h5>'+textbookValues(e.environment)+'<h5>预期结果</h5>'+textbookValues(e.expectedResult)+'<h5>实际结果</h5>'+textbookValues(e.actualResults||[])+'<h5>实际证据引用</h5>'+textbookValues(e.evidenceReferences||[])+'<h5>限制</h5>'+textbookValues(e.limits)+'</article>').join('')+'<h4>作者验证规格（不等于实际执行）</h4>'+textbookValues(chapter.verification||'未提供')+'</details><details><summary>论断、来源位置与边界</summary>'+textbookList(chapter.claims).map(c=>'<article class="textbook-claim"><h4>'+textbookEscape(c.id)+'</h4><p>'+textbookEscape(c.text)+'</p><p>'+textbookEscape(textbookStatus(c.status))+' · 来源：'+textbookEscape(textbookList(c.sourceIds).join('、')||'原创设计')+'</p>'+textbookValues(c.locators||[])+textbookValues(c.limits)+'</article>').join('')+sources.map(textbookSourceHTML).join('')+'</details><h3>当章限制</h3>'+textbookValues(chapter.limits||[])+'</article>';}
function textbookPage(){const {book,problem}=textbookPackage(textbookReader.source);const legacy='<button class="outline" data-textbook-sample="agent">切回原短示例与历史测验</button>';if(!book)return '<div class="page-title"><div><span class="eyebrow">AGENT TEXTBOOK</span><h1>Agent 开发者教材</h1></div></div><div class="info-banner" role="alert">'+textbookEscape(problem)+'</div><div class="action-row"><button class="primary" data-textbook-chapter="c01" data-textbook-source="v05">查看 v0.5 完整 c01 原稿</button><button class="outline" data-textbook-chapter="all" data-textbook-source="v05">查看 v0.5 全书</button>'+legacy+'</div>';const chapter=book.chapters.find(c=>c.id===textbookReader.chapter);if(textbookReader.mode!=='all'&&!chapter)return '<h1>教材章节不存在</h1><p>请求的章标识不属于当前十二模块；不会替换成另一章并标为完成。</p><button class="primary" data-textbook-chapter="c01">返回 Agent 机制章节</button>'+legacy;const ordered=textbookChapterIds.map(id=>book.chapters.find(c=>c.id===id));const current=chapter?.id||'';const nav='<aside class="card book-nav textbook-nav" aria-label="新版教材十二章"><button data-textbook-chapter="all" class="'+(textbookReader.mode==='all'?'active':'')+'" '+(textbookReader.mode==='all'?'aria-current="page"':'')+'>按顺序阅读全书<small>不记录完成或认证</small></button>'+ordered.map((c,i)=>'<button data-textbook-chapter="'+textbookEscape(c.id)+'" class="'+(textbookReader.mode!=='all'&&c.id===current?'active':'')+'" '+(textbookReader.mode!=='all'&&c.id===current?'aria-current="page"':'')+'>'+String(i+1).padStart(2,'0')+' · '+textbookEscape(c.title)+'<small>'+textbookEscape(c.id)+' · '+(textbookIsPilot(book)?c.id==='c01'?'新版示范':'v0.5 原稿':'v0.5 原稿')+'</small></button>').join('')+'</aside>';const index=ordered.findIndex(c=>c.id===current),pager=textbookReader.mode==='all'?'':'<div class="action-row">'+(index>0?'<button class="outline" data-textbook-chapter="'+ordered[index-1].id+'">← 上一章</button>':'')+(index<ordered.length-1?'<button class="outline" data-textbook-chapter="'+ordered[index+1].id+'">下一章 →</button>':'')+'</div>';if(textbookIsPilot(book)&&chapter?.id==='c01'&&textbookReader.mode!=='all')return textbookPilotPageHTML(book,chapter,nav,pager,legacy);return ((chapter?.id==='c01'||textbookReader.mode==='all')?textbookComparisonHTML(book):'')+'<div class="page-title"><div><span class="eyebrow">AUTHOR TEXTBOOK · '+textbookEscape(book.version)+'</span><h1>'+textbookEscape(book.title)+'</h1><p>'+(textbookIsPilot(book)?'本轮仅改写 c01 示范；其他十一章沿用 v0.5。':'v0.5 完整原稿，仅供阅读和对照。')+' 阅读不认证职业能力。</p></div></div><div class="info-banner"><strong>'+textbookEscape(textbookStatus(book.status||'draft'))+'</strong><p>本轮由教材研发员代理编写，与网站账户的模型任务分别保存；不是按当前账户发生的真实供应商调用。</p>'+textbookReviewHTML(book)+'<details><summary>作者过程、学习起点与全书限制</summary>'+textbookValues(book.provenance)+'<h4>作者审校元数据（不作为独立审核）</h4>'+textbookValues(book.review)+textbookValues(book.learnerProfiles)+'<h4>贯穿全书的项目</h4>'+textbookValues(book.mainProject)+'<h4>统一术语</h4>'+textbookValues(book.glossary)+textbookValues(book.limitations||[])+'<h4>既有量规（尚未行业校准）</h4>'+textbookValues(book.rubric)+'</details></div><div class="action-row"><button class="primary" data-textbook-download="all">下载全书 Markdown</button>'+(textbookReader.mode!=='all'?'<button class="outline" data-textbook-download="'+textbookEscape(current)+'">下载当前章</button>':'')+legacy+'<button class="outline" data-view="curriculum">课程地图</button><button class="outline" data-view="projects">项目与原练习</button><button class="outline" data-view="reflections">历史学习复盘</button><button class="outline" data-view="product-review">当前产品达标复盘</button></div><div class="book-layout textbook-layout">'+nav+'<div class="textbook-body">'+(textbookReader.mode==='all'?ordered:[chapter]).map(c=>textbookChapterHTML(book,c)).join('')+pager+'</div></div>';}
function textbookMarkdownExport(chapterId='all',source=textbookReader.source){const {book,problem}=textbookPackage(source);if(!book)throw new Error(problem);const chapters=chapterId==='all'?textbookChapterIds.map(id=>book.chapters.find(c=>c.id===id)):book.chapters.filter(c=>c.id===chapterId);if(!chapters.length)throw new Error('当前教材不存在该章');const report=textbookContentReview(book),meta=textbookMetaFor(book);return ['# '+book.title,'','教材版本：'+book.version,textbookIsPilot(book)?'本轮仅改写c01；其他十一章保留textbook-draft-0.5原稿。':'v0.5完整原稿，本轮未改。','AI教材研发员作者草稿；不是网站账户真实供应商生成任务。','阅读、公开练习、自查与结构检查不认证职业能力；人类专家审核未完成，真实学习效果未验证。','独立AI内容审校：'+(report?textbookStatus(report.overall||report.status||report.conclusion||'见报告范围'):'未匹配当前稿'),'作者源包 SHA256（打包记录）：'+(meta?.sourceSha256||'未提供'),'','## 作者过程与限制',textbookText(book.provenance),textbookText(book.limitations||[]),'## 作者审校元数据（不作为独立审核）',textbookText(book.review),'## 学习起点',textbookText(book.learnerProfiles),...(textbookIsPilot(book)&&chapterId==='c01'?['## 本章具体案例',textbookText(chapters[0].chapterCase)]:['## 全书主项目',textbookText(book.mainProject)]),'## 统一术语',textbookText(book.glossary),'## 既有量规',textbookText(book.rubric),...chapters.flatMap(c=>['','## '+c.id+' · '+c.title,'章版本：'+(c.version||book.version),'学习目标：'+textbookText(c.objectives),'先修：'+textbookText(c.prerequisites),...(Array.isArray(c.readingLessons)?['### 示范阅读入口',textbookText(c.readingIntro),...c.readingLessons.flatMap(l=>['### '+l.title,l.coreQuestion,l.bodyMarkdown,'小练习：'+l.checkQuestion,'参考解析：'+l.checkAnswer]),'### 原目标、教案与证据补充',textbookText(c.objectiveCoverage||c.objectiveMapping||c.objectiveRouting||book.objectiveDisposition||[]),textbookText(c.chapterCase)]:[]),...c.sections.flatMap(s=>['','### '+s.title,s.bodyMarkdown]),'','### 知识点与直接情景题',...textbookList(c.knowledgePoints).flatMap(p=>['#### '+p.id+' · '+p.title,p.explanation||'','情景题 '+(p.questionId||'')+'：'+textbookText(p.question||p.directQuestion||p.primaryQuestion||''),'参考结论：'+(p.answer||''),'解析：'+(p.analysis||''),'迁移：'+textbookText(p.transfer||p.transferQuestion||''),'对应目标：'+textbookText(p.objectiveIds),'对应练习：'+textbookText(p.exerciseIds),'来源与支持范围：'+textbookText({sourceIds:p.sourceIds,supportScope:p.supportScope})]),'### 分层练习与解析',...textbookList(c.exercises).flatMap(e=>['#### '+e.id+' · '+textbookStatus(e.level),e.task||'','输入：'+textbookText(e.input),'提交物：'+textbookText(e.deliverables),'参考解法：'+textbookText(e.referenceSolution),'反馈：'+textbookText(e.feedback),'迁移：'+textbookText(e.transferPrompt),'正常/边界/失败预期：'+textbookText({normal:e.normal,boundary:e.boundary,failure:e.failure}),'执行状态：'+textbookStatus(e.executionStatus||'not_run')]),'### 案例与验证状态',textbookText(c.examples),textbookText(c.verification),'### 论断与来源',textbookText(c.claims),...textbookList(book.sources).filter(s=>textbookList(c.sourceIds).includes(s.id)).map(textbookText),'### 当章限制',textbookText(c.limits)]),'','## 独立AI内容审校记录（仅匹配当前源包才适用）',report?textbookText(report):'未匹配当前稿；不能继承历史结论。'].join('\n');}
function textbookDownload(chapterId,source=textbookReader.source){try{const {book,problem}=textbookPackage(source);if(!book)throw new Error(problem);const filename='Agent教材-'+book.version+'-'+(chapterId==='all'?'全书':chapterId)+'.md';downloadMarkdown(textbookMarkdownExport(chapterId,source),filename);toast('已请求下载教材与证据状态；请保留文件。');}catch(error){toast(error.message||'教材导出失败');}}
document.addEventListener('click',event=>{const anchor=event.target.closest?.('[data-textbook-anchor]');if(anchor){event.preventDefault();const id=anchor.dataset.textbookAnchor;if(!/^textbook-(f0[12]|c0[123]|e0[1-5]|p0[12])-(scope|outcomes|concepts|case|example|practice|validation|sources|reflection)$/.test(id)&&!/^textbook-lesson-c01-read-(flow|loop|observation|stop)$/.test(id))return;const target=document.getElementById(id);target?.scrollIntoView?.({block:'start'});const heading=target?.querySelector?.('h3,h4');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});return;}const button=event.target.closest?.('button');if(!button)return;if(button.dataset.textbookChapter){const id=button.dataset.textbookChapter;if(id!=='all'&&!textbookChapterIds.includes(id))return;navigate('book','agent',{textbookChapter:id,textbookSource:button.dataset.textbookSource||textbookReader.source});return;}if(button.dataset.textbookSample){if(!modules.some(m=>m.id===button.dataset.textbookSample))return;navigate('book',button.dataset.textbookSample,{legacy:true});return;}if(button.dataset.textbookDownload)textbookDownload(button.dataset.textbookDownload,button.dataset.textbookDownloadSource||textbookReader.source);});
